package com.example.prayerhelper;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.junit.Assert;
import org.junit.Test;

public class PrayerHelperPluginTest {

    public static void main(String[] args) throws Exception {
        ExternalPluginManager.loadBuiltin(PrayerHelperPlugin.class);
        RuneLite.main(args);
    }

    @Test
    public void isPrayerLowReturnsTrueAtThreshold() {
        Assert.assertTrue(PrayerHelperPlugin.isPrayerLow(10, 10));
    }

    @Test
    public void isPrayerLowReturnsFalseAboveThreshold() {
        Assert.assertFalse(PrayerHelperPlugin.isPrayerLow(11, 10));
    }
}

package com.example.prayerhelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;

public class PrayerHelperOverlay extends Overlay {
    private static final Color WARNING_COLOR = new Color(211, 47, 47);

    private final PrayerHelperPlugin plugin;
    private final PrayerHelperConfig config;
    private final PanelComponent panelComponent = new PanelComponent();

    @Inject
    public PrayerHelperOverlay(PrayerHelperPlugin plugin, PrayerHelperConfig config) {
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.enabled() || !config.showOverlay() || !plugin.isLowPrayerActive()) {
            return null;
        }

        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(LineComponent.builder()
            .left("Prayer Helper")
            .right("Warning")
            .leftColor(WARNING_COLOR)
            .rightColor(WARNING_COLOR)
            .build());
        panelComponent.getChildren().add(LineComponent.builder()
            .left("Prayer at or below")
            .right(String.valueOf(config.prayerThreshold()))
            .build());

        return panelComponent.render(graphics);
    }
}

package com.example.prayerhelper;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("prayerhelper")
public interface PrayerHelperConfig extends Config {

    @ConfigItem(
        keyName = "enabled",
        name = "Enable plugin",
        description = "Enable low prayer reminder"
    )
    default boolean enabled() {
        return true;
    }

    @Range(
        min = 1,
        max = 99
    )
    @ConfigItem(
        keyName = "prayerThreshold",
        name = "Prayer threshold",
        description = "Show warning when current prayer is at or below this value"
    )
    default int prayerThreshold() {
        return 10;
    }

    @ConfigItem(
        keyName = "showOverlay",
        name = "Show overlay",
        description = "Show on-screen warning overlay"
    )
    default boolean showOverlay() {
        return true;
    }
}

package com.example.prayerhelper;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Prayer Helper",
    description = "Warns when prayer points fall below a configurable threshold",
    tags = {"prayer", "warning", "overlay"}
)
public class PrayerHelperPlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private PrayerHelperOverlay overlay;

    @Inject
    private PrayerHelperConfig config;

    private boolean lowPrayerActive;

    @Provides
    PrayerHelperConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(PrayerHelperConfig.class);
    }

    @Override
    protected void startUp() {
        overlayManager.add(overlay);
        lowPrayerActive = false;
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(overlay);
        lowPrayerActive = false;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING) {
            lowPrayerActive = false;
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        if (!config.enabled() || event.getSkill() != Skill.PRAYER) {
            return;
        }

        lowPrayerActive = isPrayerLow(event.getBoostedLevel(), config.prayerThreshold());
    }

    boolean isLowPrayerActive() {
        return lowPrayerActive;
    }

    static boolean isPrayerLow(int currentPrayer, int threshold) {
        return currentPrayer <= threshold;
    }
}
